  if (launchDate) {
    answer += "Aurora launches on " + launchDate + ".";
  }
  if (owner) {
    answer += "The launch is owned by " + owner + ".";
  }
  if (securityOwner) {
    answer += "The security sign-off is owned by " + securityOwner + ".";
  }

  console.log(answer);
}
